sem_t resource_sem;
int initial_count = 3; // Max simultaneous users

// Initialize semaphore (shared=0, value=initial_count)
sem_init(&resource_sem, 0, initial_count);

// --- Thread 1 acquires access ---
sem_wait(&resource_sem); 

// Critical Section (Access shared resource)

sem_post(&resource_sem);
// --- Access released ---

sem_destroy(&resource_sem);
